with account_summary as (select account_id, count(amount) as amount_count, sort_array(collect_set(txn_type)) as txn_type_list from transactions where merchant in ('7-Eleven', 'Amazon', 'Shell') group by account_id) select a.id, a.opened_date, as.amount_count, as.txn_type_list from accounts a join account_summary as on a.id = as.account_id where as.amount_count >= 6 order by a.id desc;
